const r = $input.first().json;
const tasa = r.rates?.DOP;
if (r.result !== 'success' || typeof tasa !== 'number') {
  throw new Error('La API no devolvio una tasa DOP valida');
}
return [{ json: { fecha: new Date().toISOString().slice(0, 10), tasa } }];

// la primera fila es la de hoy, la segunda la ultima guardada antes
const filas = $input.all().map((i) => i.json);
const [hoy, previa] = filas;

const cambio = previa ? Number((hoy.tasa - previa.tasa).toFixed(4)) : null;
const promedio = filas.reduce((a, f) => a + f.tasa, 0) / filas.length;

let texto = `Tasa USD a DOP del ${hoy.fecha}: ${hoy.tasa.toFixed(2)}.`;
if (cambio !== null) {
  const sentido = cambio > 0 ? 'subio' : cambio < 0 ? 'bajo' : 'se mantuvo';
  texto += ` Respecto al ${previa.fecha} ${sentido}${cambio === 0 ? '' : ' ' + Math.abs(cambio).toFixed(2)}.`;
}
if (filas.length > 1) {
  texto += ` Promedio de los ultimos ${filas.length} dias guardados: ${promedio.toFixed(2)}.`;
}

return [{ json: { fecha: hoy.fecha, tasa: hoy.tasa, anterior: previa?.tasa ?? null, cambio, promedio: Number(promedio.toFixed(4)), dias: filas.length, texto } }];
